/* ===== SURIOTA FOOTER v6 — REFINED DARK GREEN ===== */

/* Section bg: deep refined green (header tone, but darker for footer hierarchy) */
.elementor-element-1334e72c{background:#0F5132 !important;position:relative;padding:44px 0 28px !important;color:#fff}
.elementor-element-1334e72c::before{content:"";position:absolute;top:0;left:0;right:0;height:1px;background:rgba(255,255,255,.08);z-index:2}

/* Force 4-col equal layout, no wrap */
.elementor-element-1334e72c > .elementor-container{flex-wrap:nowrap !important;gap:40px;max-width:1240px;margin:0 auto;padding:0 24px}
.elementor-element-1334e72c > .elementor-container > .elementor-column{width:25% !important;flex:1 1 25% !important;min-width:0}

/* H4 titles — single clean underline, white */
.elementor-element-1334e72c .elementor-widget-heading h4.elementor-heading-title,
.elementor-element-1334e72c .elementor-widget-heading h2.elementor-heading-title{
  margin:0 0 16px !important;
  padding:0 0 10px !important;
  font:600 11px/1.2 'Plus Jakarta Sans',system-ui,sans-serif !important;
  letter-spacing:.18em !important;
  text-transform:uppercase !important;
  color:#fff !important;
  border-bottom:1px solid rgba(255,255,255,.18) !important;
  display:block;
}
.elementor-element-1334e72c .elementor-widget-heading h4.elementor-heading-title::after,
.elementor-element-1334e72c .elementor-widget-heading h2.elementor-heading-title::after{content:none !important}
.elementor-element-1334e72c .elementor-widget-heading{margin-bottom:0 !important}

/* Icon-list (Services + Products) — minimal rows */
.elementor-element-1334e72c .elementor-widget-icon-list{margin-top:0 !important}
.elementor-element-1334e72c .elementor-icon-list-items{padding:0 !important;margin:0 !important;display:flex;flex-direction:column;gap:0;list-style:none}
.elementor-element-1334e72c .elementor-icon-list-item{margin:0 !important;padding:4px 0 !important;line-height:1.2 !important}
.elementor-element-1334e72c .elementor-icon-list-item a{color:rgba(255,255,255,.72) !important;text-decoration:none !important;font:500 13px/1.3 'Plus Jakarta Sans',system-ui,sans-serif !important;padding:0 !important;transition:color .15s ease}
.elementor-element-1334e72c .elementor-icon-list-item a:hover{color:#fff !important}
.elementor-element-1334e72c .elementor-icon-list-text{padding:0 !important}
.elementor-element-1334e72c .elementor-icon-list-icon{display:none !important}

/* Social row — square, monochrome with subtle hover */
.elementor-element-1334e72c .sx-foot-social{display:flex;flex-wrap:wrap;gap:8px;margin:0 0 18px;padding:0;list-style:none}
.elementor-element-1334e72c .sx-foot-social a{display:inline-flex;align-items:center;justify-content:center;width:32px;height:32px;border-radius:6px;background:rgba(255,255,255,.08);color:rgba(255,255,255,.85);transition:background .15s ease, color .15s ease, transform .15s ease;border:1px solid rgba(255,255,255,.06)}
.elementor-element-1334e72c .sx-foot-social a:hover{background:rgba(255,255,255,.14);color:#fff;border-color:rgba(255,255,255,.18)}
.elementor-element-1334e72c .sx-foot-social svg{width:15px;height:15px;display:block}

/* Newsletter (Col 3, below social) */
.elementor-element-1334e72c .sx-foot-newsletter{margin-top:0;padding-top:16px;border-top:1px solid rgba(255,255,255,.12)}
.elementor-element-1334e72c .sx-foot-newsletter-title{margin:0 0 10px;padding:0 0 10px;font:600 11px/1.2 'Plus Jakarta Sans',system-ui,sans-serif;letter-spacing:.18em;text-transform:uppercase;color:#fff;border-bottom:1px solid rgba(255,255,255,.18);display:block}
.elementor-element-1334e72c .sx-foot-newsletter-desc{margin:0 0 10px;font:500 12px/1.45 'Plus Jakarta Sans',system-ui,sans-serif;color:rgba(255,255,255,.62)}
.elementor-element-1334e72c .sx-foot-newsletter-form{display:flex;gap:0;border-radius:6px;overflow:hidden;background:rgba(255,255,255,.08);border:1px solid rgba(255,255,255,.1)}
.elementor-element-1334e72c .sx-foot-newsletter-form input[type=email]{flex:1 1 auto;min-width:0;border:0;outline:0;padding:9px 12px;background:transparent;color:#fff;font:500 13px/1.2 'Plus Jakarta Sans',system-ui,sans-serif}
.elementor-element-1334e72c .sx-foot-newsletter-form input[type=email]::placeholder{color:rgba(255,255,255,.4)}
.elementor-element-1334e72c .sx-foot-newsletter-form button{border:0;background:#fff;color:#0F5132;padding:0 14px;font:700 11px/1 'Plus Jakarta Sans',system-ui,sans-serif;letter-spacing:.1em;text-transform:uppercase;cursor:pointer;transition:background .15s ease}
.elementor-element-1334e72c .sx-foot-newsletter-form button:hover{background:#F59E0B;color:#fff}

/* Brand block (Col 4) overrides — center logo, tagline, contact */
.elementor-element-1334e72c .sx-foot-brand{display:flex;flex-direction:column;align-items:center;gap:12px;text-align:center}
.elementor-element-1334e72c .sx-foot-brand-logo{display:inline-flex;align-items:center;justify-content:center;width:auto;max-width:240px;margin:0 auto;padding:0;text-decoration:none}
.elementor-element-1334e72c .sx-foot-brand-logo img{display:block;width:240px;max-width:100%;height:auto;object-fit:contain;filter:none;opacity:1;transition:opacity .15s ease}
.elementor-element-1334e72c .sx-foot-brand-logo:hover img{opacity:.85}
.elementor-element-1334e72c .sx-foot-tagline{margin:0;font:600 10px/1.3 'Plus Jakarta Sans',system-ui,sans-serif;letter-spacing:.22em;text-transform:uppercase;color:rgba(255,255,255,.6)}
.elementor-element-1334e72c .sx-foot-contact{list-style:none;margin:8px 0 0;padding:0;display:flex;flex-direction:column;gap:8px;align-items:center}
.elementor-element-1334e72c .sx-foot-contact li{margin:0;padding:0;display:inline-flex;align-items:center;gap:8px;font:500 13px/1.3 'Plus Jakarta Sans',system-ui,sans-serif;color:rgba(255,255,255,.78)}
.elementor-element-1334e72c .sx-foot-ico{display:inline-flex;align-items:center;justify-content:center;width:22px;height:22px;border-radius:5px;background:rgba(245,158,11,.14);color:#F59E0B;flex:0 0 22px}
.elementor-element-1334e72c .sx-foot-contact a{color:rgba(255,255,255,.88);text-decoration:none;transition:color .15s ease}
.elementor-element-1334e72c .sx-foot-contact a:hover{color:#fff}

/* Bottom bar — darker shade for hierarchy */
.elementor-element-dc08f55{background:#0A3E26 !important;padding:14px 0 !important;border-top:1px solid rgba(255,255,255,.06)}
.elementor-element-dc08f55 > .elementor-container{max-width:1240px;margin:0 auto;padding:0 24px}
.elementor-element-dc08f55 .sx-foot-bottom{display:flex;align-items:center;justify-content:space-between;gap:16px;flex-wrap:wrap}
.elementor-element-dc08f55 .sx-foot-copy{margin:0;font:500 12px/1.3 'Plus Jakarta Sans',system-ui,sans-serif;color:rgba(255,255,255,.5)}
.elementor-element-dc08f55 .sx-foot-legal{display:flex;flex-wrap:wrap;gap:20px;list-style:none;margin:0;padding:0}
.elementor-element-dc08f55 .sx-foot-legal a{color:rgba(255,255,255,.55);text-decoration:none;font:500 12px/1.3 'Plus Jakarta Sans',system-ui,sans-serif;transition:color .15s ease}
.elementor-element-dc08f55 .sx-foot-legal a:hover{color:#fff}

/* Responsive */
@media (max-width:880px){
  .elementor-element-1334e72c > .elementor-container{flex-wrap:wrap !important;gap:32px}
  .elementor-element-1334e72c > .elementor-container > .elementor-column{width:50% !important;flex:1 1 50% !important}
}
@media (max-width:540px){
  .elementor-element-1334e72c{padding:32px 0 24px !important}
  .elementor-element-1334e72c > .elementor-container > .elementor-column{width:100% !important;flex:1 1 100% !important}
  .elementor-element-1334e72c .sx-foot-brand-logo img{width:200px}
  .elementor-element-dc08f55 .sx-foot-bottom{flex-direction:column;align-items:flex-start;gap:10px}
}
/* === FIX: brighter item text in Products + Our Services lists === */
.elementor-element-1334e72c .elementor-icon-list-item a,
.elementor-element-1334e72c .elementor-icon-list-item span.elementor-icon-list-text,
.elementor-element-1334e72c .elementor-icon-list-item .elementor-icon-list-text{
  color:#FFFFFF !important;
  opacity:1 !important;
  font-weight:500 !important;
  font-size:13.5px !important;
  letter-spacing:.01em !important;
}
.elementor-element-1334e72c .elementor-icon-list-item a:hover,
.elementor-element-1334e72c .elementor-icon-list-item:hover .elementor-icon-list-text{
  color:#FBBF24 !important;
}
